document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("[data-mini-test]").forEach(function(t){var o=t.querySelector(".mini-test-submit"),c=t.querySelector(".mini-test-reset"),r=t.querySelector(".mini-test-results");function l(){t.querySelectorAll('input[type="radio"]').forEach(function(i){i.checked=!1}),t.querySelectorAll(".mini-test-question").forEach(function(i){i.classList.remove("mini-correct","mini-wrong");var n=i.querySelector(".mini-test-solution");n&&(n.open=!1)}),r&&(r.style.display="none")}o&&o.addEventListener("click",function(){var i=Array.prototype.slice.call(t.querySelectorAll(".mini-test-question")),n=0;i.forEach(function(e){var f=e.getAttribute("data-mini-answer"),a=e.querySelector('input[type="radio"]:checked'),u=e.querySelector(".mini-test-solution");e.classList.remove("mini-correct","mini-wrong"),a&&a.value===f?(n+=1,e.classList.add("mini-correct")):e.classList.add("mini-wrong"),u&&(u.open=!0)});var s=i.length||10,m=Math.round(n/s*100);t.querySelectorAll(".mini-test-score, .mini-test-score-hi").forEach(function(e){e.textContent=n+"/"+s}),t.querySelectorAll(".mini-test-accuracy, .mini-test-accuracy-hi").forEach(function(e){e.textContent=m+"%"}),r&&(r.style.display="block")}),c&&c.addEventListener("click",l),l()})});
